    const encodeValue = (value) => {
        const textarea = document.createElement('textarea');
        textarea.textContent = value;

        return textarea.innerHTML;
    };

    const addChangeEvent = (elm) => {
        elm.addEventListener('change', (evt) => {
            evt.preventDefault();

            elm = evt.target.closest('.wf-filesystem');

            if (!elm) {
                return;
            }

            const items = [], controls = elm.parentNode.querySelectorAll('.wf-filesystem');

            controls.forEach((control) => {
                const data = {};

                control.querySelectorAll('input[name], select[name], textarea[name]').forEach((input, i) => {
                    const name = input.getAttribute('name');
                    const val = input.value;

                    const parts = name.split(/\[|\]/).filter(Boolean);

                    // reset name
                    let key = '';

                    if (parts.length > 1) {
                        key = parts.length == 3 ? parts[2] : parts[3];
                    }

                    // must have "key"
                    if (key != '') {
                        // encode and set value
                        data[key] = encodeValue(val);
                    }
                });

                items.push(data);
            });

            // update hidden input
            const hiddenInput = elm.parentNode.querySelector('input[name][type="hidden"]');

            hiddenInput.value = JSON.stringify(items);
            hiddenInput.classList.add('isdirty');

            // trigger for isdirty state change
            hiddenInput.dispatchEvent(new Event('change'));
        });
    };

    const initSortable = (container) => {
        let dragImage = null;

        Sortable(container, {
            direction: 'vertical',
            handle: '.form-field-repeatable-item-control',
            placeholder: 'sortable-placeholder',
            filter: '.wf-filesystem',
            dragImage: true,
            init: (e) => {
                if (container.querySelectorAll('.wf-filesystem').length < 2) {
                    e.state = false;
                }
            },
            start: (e) => {
                let elmWidth = 0;
                // get cumulative width of children
                for (const node of e.element.children) {
                    elmWidth += node.offsetWidth;
                }

                e.placeholder.style.width = `${elmWidth}px`;
                e.element.style.width = `${elmWidth}px`;

                dragImage = e.element.cloneNode(true);
                dragImage.classList.add('wf-filesystem-placeholder');

                document.body.appendChild(dragImage);
                e.event.dataTransfer.setDragImage(dragImage, elmWidth, 0);
            },
            stop: (e) => {
                e.element.dispatchEvent(new Event('change'));
                e.element.style.width = '';

                if (dragImage && dragImage.parentNode) {
                    dragImage.remove();
                    dragImage = null;
                }
            }
        });
    };

    const setup = () => {
        document.querySelectorAll('.wf-filesystem').forEach((container) => {

            container.parentNode.querySelector('select[data-toggle]').addEventListener('toggle:hidden', (evt) => {
                const target = evt.target;

                if (target.value == '') {
                    target.closest('.wf-filesystem').classList.add('wf-filesystem-inherit');
                } else {
                    target.closest('.wf-filesystem').classList.remove('wf-filesystem-inherit');
                }

            });

            initSortable(container);
        });

        document.querySelectorAll('.wf-filesystem').forEach((ctrl) => {
            addChangeEvent(ctrl);

            ctrl.parentNode.addEventListener('repeatable:create', (evt) => {
                const elm = evt.detail;

                addChangeEvent(elm);

                elm.addEventListener('repeatable:delete', (evt) => {
                    elm.dispatchEvent(new Event('change'));
                });

                elm.dispatchEvent(new Event('change'));
            });

            ctrl.parentNode.addEventListener('repeatable:delete', (evt) => {
                ctrl.dispatchEvent(new Event('change'));
            });
        });
    };

