    function htmlspecialchars_decode(str) {
        var reverseEntities = {
            '&lt;': '<',
            '&gt;': '>',
            '&amp;': '&',
            '&quot;': '"',
            '&apos;': "'"
        };
        return str.replace(/&(#)?([\w]+);/g, function (all, numeric, value) {
            if (numeric) {
                return String.fromCharCode(value);
            }

            return reverseEntities[all];
        });
    }

