    const dataToggle = (event) => {
        const { target } = event;
        const key = target.getAttribute('data-toggle');
        const value = target.value;

        const parent = target.closest('.control-group').parentNode;

        parent.querySelectorAll('[data-toggle-target]').forEach((element) => {
            // hide all
            element.hidden = true;

            element.querySelectorAll('input,select,textarea').forEach((input) => {
                input.disabled = true;
            });

            target.dispatchEvent(new Event('toggle:hidden'));
        });

        if (value) {
            const item = parent.querySelector(`[data-toggle-target="${key}-${value}"]`);

            if (item) {
                item.hidden = false;

                item.querySelectorAll('input,select,textarea').forEach((input) => {
                    input.disabled = false;
                });

                target.dispatchEvent(new Event('toggle:visible'));
            }
        }
    };

    function init() {
        let isInit = true;

        // setup various controls
        BlockFormats.setup();
        Fonts.setup();
        Filetypes.setup();
        StyleFormats.setup();
        FileSystem.setup();

        // Layout
        Layout.createLayout();

        // init toggle
        document.querySelectorAll('select[data-toggle]').forEach((select) => {
            dataToggle({ target: select });
        });

        // global change event listener
        const form = document.querySelector('.ui-jce > form');

        if (form) {
            form.addEventListener('change', function (e) {
                // Skip on init
                if (isInit) {
                    return;
                }
        
                // data-toggle
                if (e.target.matches('select[data-toggle]')) {
                    dataToggle(e);
                }
        
                // only process submittable form elements
                if (!e.target.matches('input[name],select[name],textarea[name]')) {
                    return;
                }
        
                const elm = e.target;
        
                // Skip name values that are not submittable
                if (elm.name.indexOf('jform[config]') === -1) {
                    return;
                }
        
                // trigget Layout events
                Layout.triggerChange(e);
        
                // Get name as escaped string
                const name = elm.name.replace(/[!"#$%&()*+,./:;<=>?@[\]^`{|}~]/g, '\\$1');
        
                // Add class to this element and any that share its name, e.g., param[]
                this.querySelectorAll(`[name="${name}"]`).forEach((element) => {
                    element.classList.add('isdirty');
                });
        
                // Add "isdirty" class to each input on change
                elm.classList.add('isdirty');
            });

            Layout.updateTheme(form.querySelector('select[name$="[editor][toolbar_theme]"]').value);
        }

        // Additional Features
        document.querySelectorAll('.editor-features input[type="checkbox"]').forEach((checkbox) => {
            checkbox.addEventListener('click', () => {
                Layout.setPlugins();
            });
        });

        // Reset input[type="number"] if < 1
        document.querySelectorAll('input[type="number"]').forEach((input) => {
            input.addEventListener('change', () => {
                if (input.value < 1) {
                    input.value = '';
                }
            });
        });

        // Fix encoding of some characters in text fields
        document.querySelectorAll('input[data-decode]').forEach((input) => {
            const value = input.value;

            if (value) {
                input.value = htmlspecialchars_decode(value);
            }
        });

        // Secondary tabs within profile content
        document.querySelectorAll('.nav-tabs li').forEach((tab) => {
            tab.addEventListener('click', (e) => {
                e.preventDefault();

                const index = Array.from(tab.parentNode.children).indexOf(tab);
                const container = tab.closest('.tabbable');

                Array.from(tab.parentNode.children).forEach((child) => {
                    child.classList.remove('active', 'show', 'hide');
                });

                tab.classList.add('active', 'show');

                const tabPanes = container.querySelectorAll('.tab-content .tab-pane');

                tabPanes.forEach((pane) => {
                    pane.classList.remove('active', 'show', 'hide');
                });

                tabPanes[index].classList.add('active', 'show');
            });
        });

        document.querySelector('.ui-jce').classList.remove('loading');

        isInit = false;
    }

    document.addEventListener('DOMContentLoaded', () => {
        window.setTimeout(() => {
            init();
        }, 100);
    });

    window.WfSelectUsers = () => {
        const [userElm, userIdElm, userSelectElm] = document.querySelectorAll('#jform_users, #jform_users_id, #jform_users_select');

        const name = userElm.getAttribute('value');
        const id = userIdElm.value;

        const opt = new Option(name, id);

        // clear id and value
        userElm.value = '';
        userIdElm.value = '';

        // get existing select value
        let value = userSelectElm.value;

        // cast as array
        if (!Array.isArray(value)) {
            value = [value];
        }

        // add new id
        value.push(id);

        // add new option to select list if it does not exist
        if (!userSelectElm.querySelector(`option[value="${id}"]`)) {
            userSelectElm.appendChild(opt);
        }

        // update value and "chosen"
        userSelectElm.value = value;
        userSelectElm.dispatchEvent(new Event('change'));

        // update fancy-select "choices"
        const fancySelect = userSelectElm.closest('joomla-field-fancy-select');

        if (fancySelect && fancySelect.choicesInstance) {
            fancySelect.choicesInstance.setValue([{ value: id, label: name }]);
        }
    };

